-- Executed after the reusable Week 1 fixture setup in the same rolled-back transaction.
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true(pg_temp.denied($q$select alvis_new_capture('30000000-0000-4000-8000-000000000001','Recording','Training','recording-v1')$q$),'worker cannot create captures');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true(pg_temp.denied($q$select alvis_new_capture('30000000-0000-4000-8000-000000000002','Recording','Training','recording-v1')$q$),'foreign asset denied');
select pg_temp.assert_true(pg_temp.denied($q$select alvis_new_capture('30000000-0000-4000-8000-000000000001','Recording','Training','other-policy')$q$),'consent required');
select set_config('alvis.cap',alvis_begin_capture('30000000-0000-4000-8000-000000000001','Actual capture contract test','Training simulation','recording-v1','f9000000-0000-4000-8000-000000000001',repeat('a',64))::text,true);
create function pg_temp.cap() returns uuid language sql as $$select current_setting('alvis.cap')::uuid$$;
select pg_temp.assert_true(alvis_begin_capture('30000000-0000-4000-8000-000000000001','Actual capture contract test','Training simulation','recording-v1','f9000000-0000-4000-8000-000000000001',repeat('a',64))=pg_temp.cap(),'lost create response retry returns same capture');
select pg_temp.assert_true(pg_temp.denied($q$select alvis_begin_capture('30000000-0000-4000-8000-000000000001','Changed title','Training simulation','recording-v1','f9000000-0000-4000-8000-000000000001',repeat('a',64))$q$),'same request cannot overwrite initial capture');
select pg_temp.assert_true(pg_temp.denied($q$select alvis_capture_command(pg_temp.cap(),'upload','{"mime":"video/avi","bytes":1000}')$q$),'invalid upload format denied');
select pg_temp.assert_true(pg_temp.denied($q$select alvis_capture_command(pg_temp.cap(),'upload','{"mime":"video/mp4","bytes":104857601}')$q$),'oversized upload denied');
select set_config('alvis.upload',(alvis_capture_command(pg_temp.cap(),'upload','{"mime":"video/mp4","bytes":1000}')->>'id'),true);
select alvis_capture_command(pg_temp.cap(),'complete',jsonb_build_object('upload_id',current_setting('alvis.upload'),'checksum',repeat('a',64),'request_key','completion-one'));
select alvis_capture_command(pg_temp.cap(),'complete',jsonb_build_object('upload_id',current_setting('alvis.upload'),'checksum',repeat('a',64),'request_key','completion-one'));
select pg_temp.assert_true((select count(*)=1 from processing_jobs where capture_id=pg_temp.cap()),'duplicate completion creates one job');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select pg_temp.assert_true((select count(*)=0 from captures),'other-tenant capture hidden');
select pg_temp.assert_true(pg_temp.denied($q$select alvis_capture_command(pg_temp.cap(),'regenerate','{}')$q$),'other-tenant command denied');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=0 from captures),'worker cannot read recordings');
select pg_temp.assert_true((select count(*)=0 from capture_uploads),'worker cannot see storage keys');
select pg_temp.assert_true(pg_temp.denied($q$select alvis_claim_job()$q$),'browser cannot claim jobs');
reset role;
set local role service_role;
select set_config('alvis.job',id::text,true),set_config('alvis.token',lease_token::text,true) from alvis_claim_job();
select pg_temp.assert_true((select count(*)=0 from alvis_claim_job()),'live lease cannot be claimed twice');
select pg_temp.assert_true(not alvis_heartbeat(current_setting('alvis.job')::uuid,gen_random_uuid()),'stale worker cannot heartbeat');
select pg_temp.assert_true(pg_temp.denied($q$select alvis_finish_job(current_setting('alvis.job')::uuid,gen_random_uuid(),'{}')$q$),'stale worker cannot commit');
select pg_temp.assert_true(pg_temp.denied($q$select alvis_finish_job(current_setting('alvis.job')::uuid,current_setting('alvis.token')::uuid,jsonb_build_object('bytes',1000,'checksum',repeat('a',64),'duration',181,'storage_key','invalid'))$q$),'decoded duration cannot exceed limit');
select alvis_fail_job(current_setting('alvis.job')::uuid,current_setting('alvis.token')::uuid,'TRANSIENT',true);
select pg_temp.assert_true((select status='queued' and attempts=1 from processing_jobs where id=current_setting('alvis.job')::uuid),'temporary failure queues bounded retry');
update processing_jobs set next_attempt_at=now() where id=current_setting('alvis.job')::uuid;
select set_config('alvis.job',id::text,true),set_config('alvis.token',lease_token::text,true) from alvis_claim_job();
select alvis_finish_job(current_setting('alvis.job')::uuid,current_setting('alvis.token')::uuid,jsonb_build_object('bytes',1000,'checksum',repeat('a',64),'duration',45,'storage_key','10000000-0000-4000-8000-000000000001/'||pg_temp.cap()::text||'/verified/recording'));
select set_config('alvis.job',id::text,true),set_config('alvis.token',lease_token::text,true) from alvis_claim_job();
select alvis_finish_job(current_setting('alvis.job')::uuid,current_setting('alvis.token')::uuid,'{"segments":[{"text":"An observed training action","start_ms":125,"end_ms":2000}]}');
select pg_temp.assert_true((select start_ms=125 and end_ms=2000 from sources where capture_id=pg_temp.cap()),'provider timestamps preserved');
select set_config('alvis.source',(select id::text from sources where capture_id=pg_temp.cap()),true);
select set_config('alvis.job',id::text,true),set_config('alvis.token',lease_token::text,true) from alvis_claim_job();
select pg_temp.assert_true(pg_temp.denied($q$select alvis_finish_job(current_setting('alvis.job')::uuid,current_setting('alvis.token')::uuid,'{"content":{"status":"approved"}}')$q$),'invalid output cannot become draft');
select pg_temp.assert_true((select current_revision_id is null from captures where id=pg_temp.cap()),'failed model commit rolls back draft');
-- SQL boundary fixture result, not a live model/media result.
select alvis_finish_job(current_setting('alvis.job')::uuid,current_setting('alvis.token')::uuid,
 jsonb_build_object('content',(select replace(content::text,'40000000-0000-4000-8000-000000000001',current_setting('alvis.source'))::jsonb from knowledge_revisions where id='60000000-0000-4000-8000-000000000001')));
select pg_temp.assert_true((select status='draft' and not index_ready from knowledge_revisions where capture_id=pg_temp.cap()),'worker only creates unverified draft');
select pg_temp.assert_true(pg_temp.denied($q$select alvis_transition(current_revision_id,'approve',null,'','AI publish','invalid-ai') from captures where id=pg_temp.cap()$q$),'worker has no publication RPC authority');
select set_config('alvis.job',id::text,true),set_config('alvis.token',lease_token::text,true) from alvis_claim_job();
select alvis_finish_job(current_setting('alvis.job')::uuid,current_setting('alvis.token')::uuid,jsonb_build_object('questions',jsonb_build_array(jsonb_build_object('id','why','target_field','reason','question','What led you to choose this action?','gap','Unconfirmed reason','source_ids',jsonb_build_array(current_setting('alvis.source'))))));
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=0 from sources where capture_id=pg_temp.cap()),'worker cannot read unapproved transcript');
select pg_temp.assert_true((select count(*)=0 from debrief_items),'worker cannot read debrief');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select alvis_transition(id,'save',jsonb_set(content,'{steps,0,rationale}','null'::jsonb),content_hash,'','') from knowledge_revisions where capture_id=pg_temp.cap();
select pg_temp.assert_true(pg_temp.denied($q$select alvis_transition(id,'submit',null,content_hash,'','') from knowledge_revisions where capture_id=pg_temp.cap()$q$),'unconfirmed step rationale blocks submission');
select alvis_transition(id,'save',jsonb_set(content,'{steps,0,rationale}','"Applicability"'::jsonb),content_hash,'','') from knowledge_revisions where capture_id=pg_temp.cap();
select alvis_capture_command(pg_temp.cap(),'debrief',jsonb_build_object('question_id',(select id from debrief_items where capture_id=pg_temp.cap()),'answer','The change and location informed my choice.','cannot_confirm',false));
select pg_temp.assert_true(pg_temp.denied($q$select alvis_transition(current_revision_id,'submit',null,(select content_hash from knowledge_revisions where id=current_revision_id),'','') from captures where id=pg_temp.cap()$q$),'changed evidence blocks stale draft submission');
select alvis_capture_command(pg_temp.cap(),'transcript',jsonb_build_object('expected_version',1,'segments',jsonb_build_array(jsonb_build_object('id',current_setting('alvis.source'),'text','Corrected observation'))));
select pg_temp.assert_true((select count(*)=2 from sources where capture_id=pg_temp.cap() and kind='transcript'),'correction appends evidence');
select pg_temp.assert_true((select text_content='An observed training action' from sources where id=current_setting('alvis.source')::uuid),'old evidence preserved');
select pg_temp.assert_true(pg_temp.denied($q$select alvis_capture_command(pg_temp.cap(),'transcript',jsonb_build_object('expected_version',1,'segments','[]'::jsonb))$q$),'stale corrections denied');
select pg_temp.assert_true(pg_temp.denied($q$update sources set text_content='overwritten' where capture_id=pg_temp.cap()$q$),'evidence direct writes denied');
reset role;
set local role service_role;
select set_config('alvis.job',id::text,true),set_config('alvis.token',lease_token::text,true) from alvis_claim_job();
select pg_temp.assert_true(pg_temp.denied($q$select alvis_finish_job(current_setting('alvis.job')::uuid,current_setting('alvis.token')::uuid,jsonb_build_object('content',(select content from knowledge_revisions where capture_id=pg_temp.cap())))$q$),'old generation cannot reuse superseded citations');
select alvis_finish_job(current_setting('alvis.job')::uuid,current_setting('alvis.token')::uuid,jsonb_build_object('content',(select replace(content::text,current_setting('alvis.source'),(select id::text from sources where capture_id=pg_temp.cap() and kind='transcript' and evidence_version=2))::jsonb from knowledge_revisions where capture_id=pg_temp.cap())));
select pg_temp.assert_true((select count(*)=1 from extraction_proposals where capture_id=pg_temp.cap()),'regeneration creates proposal');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true(pg_temp.denied($q$select alvis_capture_command(pg_temp.cap(),'accept',jsonb_build_object('proposal_id',(select id from extraction_proposals where capture_id=pg_temp.cap()),'expected_hash','stale'))$q$),'stale acceptance denied');
select alvis_transition(id,'save',jsonb_set(content,'{title}','"Expert edited title"'::jsonb),content_hash,'','') from knowledge_revisions where capture_id=pg_temp.cap();
select pg_temp.assert_true(pg_temp.denied($q$select alvis_capture_command(pg_temp.cap(),'accept',jsonb_build_object('proposal_id',(select id from extraction_proposals where capture_id=pg_temp.cap()),'expected_hash',(select content_hash from knowledge_revisions where capture_id=pg_temp.cap())))$q$),'proposal cannot overwrite newer expert edits');
select pg_temp.assert_true((select content->>'title'='Expert edited title' from knowledge_revisions where capture_id=pg_temp.cap()),'expert edit remains intact');
select alvis_transition(id,'save',jsonb_set(content,'{title}','"Synthetic judgment"'::jsonb),content_hash,'','') from knowledge_revisions where capture_id=pg_temp.cap();
select alvis_capture_command(pg_temp.cap(),'accept',jsonb_build_object('proposal_id',(select id from extraction_proposals where capture_id=pg_temp.cap()),'expected_hash',(select content_hash from knowledge_revisions where capture_id=pg_temp.cap())));
select alvis_transition(id,'submit',null,content_hash,'','') from knowledge_revisions where capture_id=pg_temp.cap();
select pg_temp.assert_true(pg_temp.denied($q$select alvis_capture_command(pg_temp.cap(),'regenerate',jsonb_build_object('expected_hash',(select content_hash from knowledge_revisions where capture_id=pg_temp.cap())))$q$),'pending capture drafts lock regeneration');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select alvis_transition(id,'approve',null,content_hash,'Human reviewer checked the actual sources.','capture-review') from knowledge_revisions where capture_id=pg_temp.cap();
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=1 from knowledge_revisions where capture_id=pg_temp.cap()),'approved current capture draft becomes worker knowledge');
select pg_temp.assert_true((select count(*)=1 from sources where capture_id=pg_temp.cap()),'worker sees only approved linked source snapshot');
select pg_temp.assert_true((select count(*)=0 from captures),'worker still cannot browse raw captures');
select pg_temp.assert_true((select count(*)=0 from draft_edit_history),'worker cannot read historical drafts after approval');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select count(*)>=4 from draft_edit_history where revision_id=(select current_revision_id from captures where id=pg_temp.cap())),'expert edits and prior generations preserved');
select alvis_copy_draft(unit_id) from knowledge_revisions where capture_id=pg_temp.cap();
select pg_temp.assert_true((select count(*)=2 from knowledge_revisions where capture_id=pg_temp.cap()),'correction revision preserves recording provenance');
reset role;
-- Same-organization experts cannot access another contributor's recording.
insert into memberships(organization_id,user_id,role,display_name) values('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000004','expert','Second expert');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select pg_temp.assert_true((select count(*)=0 from captures),'other expert cannot read owned capture');
select pg_temp.assert_true((select count(*)=0 from capture_uploads),'other expert cannot read upload locators');
select pg_temp.assert_true(pg_temp.denied($q$select alvis_capture_command(pg_temp.cap(),'regenerate','{}')$q$),'other expert cannot mutate capture');
reset role;
-- A valid expired lease is reclaimed, fenced against the abandoned worker, and capped.
insert into processing_jobs(organization_id,capture_id,stage,dedupe_key,status,attempts,lease_until,lease_token) values('10000000-0000-4000-8000-000000000001',pg_temp.cap(),'extract','recover-lease','running',1,now()-interval '1 minute','80000000-0000-4000-8000-000000000001');
set local role service_role;
select set_config('alvis.job',id::text,true),set_config('alvis.token',lease_token::text,true) from alvis_claim_job();
select pg_temp.assert_true((select attempts=2 from processing_jobs where dedupe_key='recover-lease'),'expired lease reclaimed with bounded attempt');
select pg_temp.assert_true(not alvis_heartbeat(current_setting('alvis.job')::uuid,'80000000-0000-4000-8000-000000000001'),'abandoned worker fenced');
select alvis_fail_job(current_setting('alvis.job')::uuid,current_setting('alvis.token')::uuid,'INVALID_MODEL_OUTPUT',false);
select pg_temp.assert_true(pg_temp.denied($q$update sources set text_content='changed' where capture_id=pg_temp.cap()$q$),'source immutability also protects privileged worker writes');
reset role;
-- Simulate interrupted final attempts; exhausted leases cannot be reclaimed.
insert into processing_jobs(organization_id,capture_id,stage,dedupe_key,status,attempts,lease_until) values('10000000-0000-4000-8000-000000000001',pg_temp.cap(),'extract','exhausted','running',3,now()-interval '1 minute');
set local role service_role;
select pg_temp.assert_true((select count(*)=0 from alvis_claim_job()),'exhausted jobs cannot run again');
select pg_temp.assert_true((select status='failed' from processing_jobs where dedupe_key='exhausted'),'exhausted lease becomes durable failure');
reset role;
rollback;
select 'PASS: capture ownership, tenant isolation, upload limits, dedupe, leases, retry bounds, model validation, source versions and review handoff';
